export interface Word {
  en: string;
  zh: string;
  image: string;
  phonics?: string;        // 代表字母（如 'Aa'）
  kk?: string;             // KK 音標
  phonicsSound?: string;   // 自然發音重點音（如 '/æ/'）
  exampleSentence?: string;
  exampleZh?: string;
}

export interface Sentence {
  en: string;
  zh: string;
}

export interface StoryScene {
  image: string;
  character: string;
  characterKey?: string;
  characterAction?: string;
  characterName: string;
  dialogue: string;
  dialogueZh: string;
  highlightWords?: string[];
  // 動畫場景：多個 emoji 組成動畫
  sceneEmojis: string[];
  // 動畫類型
  animation: 'wave' | 'bounce' | 'shake' | 'spin' | 'float' | 'tada';
}

export interface QuizQuestion {
  type: 'listen-pick' | 'match' | 'spell' | 'speak' | 'fill-blank' | 'read';
  question: string;
  options?: string[];
  answer: string;
  image?: string;
  passage?: string;   // 閱讀理解題的短文/對話（read 題型顯示，不自動播音）
}

export interface Mission {
  id: number;
  slug: string;
  level: number;
  title: string;
  titleEn: string;
  theme: string;
  themeEmoji: string;
  story: StoryScene[];
  words: Word[];
  sentences: Sentence[];
  phonicsLetters: string[];
  warmUpQuestions: QuizQuestion[];
  challenges: QuizQuestion[];
  talkTimePrompts: string[];
  reviewQuiz: QuizQuestion[];
  // ── v2 新格式（L2 起）選填 ──
  focus?: string;              // 該課重點（phonics 樣式 / 文法點）
  videoScript?: VideoLine[];   // 對話影片腳本（角色輪流；留給 Vega 拍/生）
  videoUrl?: string;           // 對話影片連結（YouTube 網址 或 mp4/R2 連結）；沒填就顯示腳本分鏡
  tip?: { zh: string; char?: string; face?: boolean };  // 小老師提醒（角色泡泡）：如「母音媽媽」「a/an 規則」「例外字直接記」；face=true 會畫出母音媽媽的臉
  goal?: { zh: string; char?: string };  // 故事任務目標（開場任務卡）：把「今天學 X」變成「幫 Finn 完成任務」
}

// 對話影片腳本一行
export interface VideoLine {
  speaker: string;   // 角色名（Finn/Coco… 或新角色）
  line: string;      // 英文台詞
  lineZh: string;    // 中文
}

